export const OVERLAYS = {"engprof--research-paper-structure":{"engprof--research-paper-structure--4-conventional-sections-imrd-format":{"claims":[{"id":"engprof--research-paper-structure--4-conventional-sections-imrd-format--v1","statement":"โครงสร้าง IMRAD (Introduction, Methods, Results, Discussion) ไม่ได้เป็นมาตรฐานมาแต่เดิม จากการสำรวจบทความในวารสารอายุรศาสตร์ชั้นนำ 4 ฉบับ (BMJ, JAMA, The Lancet, NEJM) ช่วงปี 1935-1985 พบว่า IMRAD เริ่มถูกใช้ในทศวรรษ 1940s, ขึ้นถึง 80% ในทศวรรษ 1970s และเป็นรูปแบบเดียวที่ใช้ใน original paper ในทศวรรษ 1980s","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15243643","locator":"J Med Libr Assoc. 2004;92(3):364-7 (PMC442179)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The IMRAD structure, in those journals, began to be used in the 1940s. In the 1970s, it reached 80% and, in the 1980s, was the only pattern adopted in original papers."}}]},"engprof--research-paper-structure--quick-reference-ข้อมูลแบบไหนอยู่-section-ไหน":{"claims":[{"id":"engprof--research-paper-structure--quick-reference-ข้อมูลแบบไหนอยู่-section-ไหน--v1","statement":"STROBE statement คือ checklist 22 ข้อสำหรับรายงาน observational study โดยผูกแต่ละข้อไว้กับ section: title และ abstract = ข้อ 1, introduction = ข้อ 2-3, methods = ข้อ 4-12, results = ข้อ 13-17, discussion = ข้อ 18-21, และ funding = ข้อ 22 โดย 18 ข้อใช้ร่วมกันทั้ง cohort, case-control และ cross-sectional ส่วนอีก 4 ข้อ (ข้อ 6, 12, 14, 15) เป็น design-specific","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17941714","locator":"STROBE Statement, 22-item checklist; section 'STROBE Components' (PLoS Med. 2007;4(10):e296)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These items relate to the article's title and abstract (item 1), the introduction (items 2 and 3), methods (items 4–12), results (items 13–17) and discussion sections (items 18–21), and other information (item 22 on funding). 18 items are c"}}]},"engprof--research-paper-structure--2-methodology-what-to-look-for":{"claims":[{"id":"engprof--research-paper-structure--2-methodology-what-to-look-for--v1","statement":"ARRIVE guidelines 2.0 (2020) แบ่ง checklist การรายงานงานวิจัยในสัตว์ (in vivo experiments) ออกเป็น 2 ชุดด้วยกระบวนการ Delphi คือ 'ARRIVE Essential 10' ซึ่งเป็นข้อมูลขั้นต่ำที่ต้องรายงาน และ 'Recommended Set' ซึ่งอธิบายบริบทของงานวิจัย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32663219","locator":"ARRIVE 2.0, 'ARRIVE Essential 10' and 'Recommended Set' (PLoS Biol. 2020;18(7):e3000410)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We used a Delphi exercise to prioritise and divide the items of the guidelines into 2 sets, the \"ARRIVE Essential 10,\" which constitutes the minimum requirement, and the \"Recommended Set,\" which describes the research context."}},{"id":"engprof--research-paper-structure--2-methodology-what-to-look-for--v2","statement":"สำหรับ randomized controlled trial ใน livestock และงาน food safety มาตรฐานการรายงานคือ REFLECT statement ซึ่งดัดแปลงจาก CONSORT เป็น checklist 22 ข้อ โดยแก้ไข 14 ข้อจาก CONSORT checklist และเพิ่ม sub-item อีก 1 ข้อสำหรับ challenge trial","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19926151","locator":"REFLECT 22-item checklist (Prev Vet Med. 2010;93(1):11-8); co-published in J Vet Intern Med, J Food Prot and Zoonoses Public Health","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The consensus meeting resulted in the production of the REFLECT (Reporting Guidelines For Randomized Control Trials) statement for livestock and food safety (LFS) and 22-item checklist. Fourteen items were modified from the CONSORT checklis"}}]},"engprof--research-paper-structure--4-discussion-conclusion-what-to-look-for":{"claims":[{"id":"engprof--research-paper-structure--4-discussion-conclusion-what-to-look-for--v1","statement":"แม้ limitations จะเป็นองค์ประกอบมาตรฐานของ Discussion แต่ในทางปฏิบัติมักไม่ถูกเขียนจริง การตรวจบทความ 50 เรื่องแรกที่ตีพิมพ์ปี 2005 จากวารสารวิจัยที่ถูกอ้างอิงสูงสุด 6 ฉบับ และวารสาร open-access ชั้นนำ 2 ฉบับ พบว่ามีเพียง 67 บทความ (17%) ที่ใช้คำสื่อถึง limitation, มีเพียง 4 บทความ (1%) ที่ใช้คำว่า limitation ใน abstract และมีเพียง 5 บทความที่มี section แยกสำหรับ limitations","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17346604","locator":"J Clin Epidemiol. 2007;60(4):324-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An examination of the full-text files of the first 50 articles published in 2005 in the six most-cited research journals and in two recently launched leading open-access journals showed that only 67 articles (17%) used at least one word den"}}]},"engprof--research-paper-structure--3-results-what-to-look-for":{"claims":[{"id":"engprof--research-paper-structure--3-results-what-to-look-for--v1","statement":"เกณฑ์ p < 0.05 เป็น convention ที่ใช้จริงในวรรณกรรมเพื่อแบ่ง significant กับ nonsignificant (งานวิจัยนิยาม statistically nonsignificant ว่า P ≥ .05) แต่ถ้อยคำในบทความอาจไม่ตรงกับตัวเลข ในรายงาน RCT 72 เรื่องที่ primary outcome ไม่ significant พบ spin ใน Conclusions ของ abstract 42 เรื่อง (58.3%, 95% CI 46.1-69.8) และใน Conclusions ของเนื้อความ 36 เรื่อง (50.0%, 95% CI 38.0-62.0)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20501928","locator":"JAMA. 2010;303(20):2058-64","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Articles were included if they were parallel-group RCTs with a clearly identified primary outcome showing statistically nonsignificant results (ie, P > or = .05). ... Spin was identified in the Results and Conclusions sections of the abstra"}}]},"engprof--research-paper-structure--what-is-a-research-paper":{"claims":[{"id":"engprof--research-paper-structure--what-is-a-research-paper--v1","statement":"original scientific article เป็นสิ่งพิมพ์คนละประเภทกับ narrative review, systematic review, meta-analysis และ editorial และงานเขียนทางการแพทย์ใช้โครงสร้างมาตรฐาน IMRAD (Introduction, Methods, Results, and Discussion)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29974882","locator":"Abstract; J Minim Access Surg. 2019;15(3):242-248","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Various types of surgical publications that exist nowadays are case report, cohort study, case-control study, randomised controlled trial narrative review, systematic review, Cochrane review, meta-analysis, editorials and leading articles. "}},{"id":"engprof--research-paper-structure--what-is-a-research-paper--v2","statement":"งานวิจัยต้นฉบับต้องบอกได้ว่าตัวมันเพิ่มอะไรให้กับองค์ความรู้ที่มีอยู่ (add to the existing knowledge) ซึ่งเป็นสิ่งที่ผู้ประเมินบทความมองหา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23478739","locator":"Abstract; JNMA J Nepal Med Assoc. 2012;52(186):95-101","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The introduction describes work already conducted in the particular area and briefly mentions how the manuscript will add to the existing knowledge."}}]},"engprof--research-paper-structure--1-introduction-what-to-look-for":{"claims":[{"id":"engprof--research-paper-structure--1-introduction-what-to-look-for--v1","statement":"Introduction ทำหน้าที่อธิบาย rationale ของการทำการศึกษา และระบุ main purpose ของงานให้ชัดเจน โดยควรกระชับ ข้อผิดพลาดที่พบบ่อยคือทบทวนวรรณกรรมยืดยาวเกินไป และไม่ระบุ objectives หรือสมมติฐานให้ชัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26731827","locator":"Abstract; J Assoc Physicians India. 2015;63(7):44-46","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Introduction section explains the rationale for undertaking the study and clearly describes the main purpose of conducting it. It should be focused, succinct and crisp. Providing an extensive and detailed literature review, not stating "}},{"id":"engprof--research-paper-structure--1-introduction-what-to-look-for--v2","statement":"หน้าที่สำคัญของ Introduction คือแสดงให้เห็นว่าทำไมการศึกษานี้จึงสำคัญ (why the study matters) ซึ่งเป็นจุดที่ผู้เขียนจำนวนมากทำได้ไม่ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33240363","locator":"Abstract; Can J Dent Hyg. 2020;54(1):42-44","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Specifically, they should demonstrate why the study matters in the introduction section of their text. Our experience in mentoring dental and dental hygiene faculty shows that some have difficulty justifying the importance of their studies "}}]}},"engprof--academic-writing":{"engprof--academic-writing--ประเภทของ-academic-papers":{"claims":[{"id":"engprof--academic-writing--ประเภทของ-academic-papers--v1","statement":"Case report มีมาตรฐานการรายงานของตัวเองคือ CARE guidelines ซึ่งเป็น checklist 13 ข้อ ได้แก่ title, key words, abstract, introduction, patient information, clinical findings, timeline, diagnostic assessment, therapeutic interventions, follow-up and outcomes, discussion, patient perspective และ informed consent","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24035173","locator":"CARE 13-item checklist (J Clin Epidemiol. 2014;67(1):46-51)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This consensus process involved 27 participants and resulted in a 13-item checklist-a reporting guideline for case reports. The primary items of the checklist are title, key words, abstract, introduction, patient information, clinical findi"}},{"id":"engprof--academic-writing--ประเภทของ-academic-papers--v2","statement":"Review article ประเภท systematic review มีมาตรฐานการรายงานคือ PRISMA 2020 ซึ่งมาแทน PRISMA 2009 ประกอบด้วย checklist 27 ข้อ, abstract checklist แยกต่างหาก และ flow diagram สำหรับ review ทั้งแบบใหม่และแบบ updated","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33782057","locator":"PRISMA 2020 27-item checklist and abstract checklist (BMJ. 2021;372:n71)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The PRISMA 2020 statement replaces the 2009 statement and includes new reporting guidance that reflects advances in methods to identify, select, appraise, and synthesise studies. ... we present the PRISMA 2020 27-item checklist, an expanded"}},{"id":"engprof--academic-writing--ประเภทของ-academic-papers--v3","statement":"งานวิจัยที่ทำในสัตว์ (in vivo experiments) มี reporting guideline เฉพาะคือ ARRIVE 2.0 ซึ่งมีทั้งหมด 21 ข้อ พร้อมเอกสาร Explanation and Elaboration ที่อธิบายเหตุผลและยกตัวอย่างการรายงานที่ดีของแต่ละข้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32663221","locator":"ARRIVE 2.0 Explanation and Elaboration, 21 items (PLoS Biol. 2020;18(7):e3000411)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It provides further information about each of the 21 items in ARRIVE 2.0, including the rationale and supporting evidence for their inclusion in the guidelines, elaboration of details to report, and examples of good reporting from the publi"}}]},"engprof--academic-writing--5-steps-to-write-a-review-article":{"claims":[{"id":"engprof--academic-writing--5-steps-to-write-a-review-article--v1","statement":"กระบวนการเขียน review article ตามคำแนะนำที่ตีพิมพ์ คือ เลือก topic ที่ผู้เขียนมีความรู้และสนใจจริง แล้วสืบค้นวรรณกรรมพร้อมวิเคราะห์เชิงวิจารณ์ จากนั้นจึงเขียนตัวบทความซึ่งประกอบด้วย abstract, introduction, body และ conclusion พร้อมตารางและรูปประกอบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38416900","locator":"Abstract; J Breast Imaging. 2023;5(4):480-485","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The process involves selecting a topic about which the authors are knowledgeable and enthusiastic, conducting a literature search and critical analysis of the literature, and writing the article, which is composed of an abstract, introducti"}},{"id":"engprof--academic-writing--5-steps-to-write-a-review-article--v2","statement":"การเขียน narrative review ทางชีวเวชศาสตร์มีขั้นตอนหลักที่ระบุได้ชัดเจน และต้องอาศัยความรู้ความเข้าใจในสาขานั้นอย่างลึกซึ้ง ไม่ใช่แค่การรวบรวมบทความมาต่อกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21800117","locator":"Abstract; Rheumatol Int. 2011;31(11):1409-1417","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Writing a review requires deep knowledge and understanding of a field. The aim of this review is to analyze the main steps in writing a narrative biomedical review and to consider points that may increase the chances of success."}}]},"engprof--academic-writing--writing-introduction-4-components-lester-lester":{"claims":[{"id":"engprof--academic-writing--writing-introduction-4-components-lester-lester--v1","statement":"Introduction ควรทบทวนเรื่องที่ศึกษา (subject และ background) ให้ครอบคลุมก่อน แล้วจึงระบุ aim ของงานให้ชัดเจนทันทีหลังจากกล่าวถึง references พื้นฐาน โดยมีเป้าหมายให้ผู้อ่านเข้าใจพื้นเรื่องได้โดยไม่ต้องไปตามอ่านงานเก่าเอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26328128","locator":"Abstract; Turk J Urol. 2013;39(Suppl 1):8-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The main goal of the introduction is to convey basic information to the readers without obligating them to investigate previous publications and to provide clues as to the results of the present study. To do this, the subject of the article"}}]},"engprof--academic-writing--writing-conclusion-body-paragraphs":{"claims":[{"id":"engprof--academic-writing--writing-conclusion-body-paragraphs--v1","statement":"การระบุ limitations ของงานตนเองเป็นส่วนที่จำเป็นในบทสรุป เพราะผู้อ่านต้องใช้ข้อมูลนี้ตีความผลให้ถูกต้อง และควรถูกมองว่าเป็น due diligence ไม่ใช่จุดอ่อนของงาน อย่างไรก็ตามการรายงาน limitations จริงในวารสารยังทำได้ไม่ดีพอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37414393","locator":"Abstract; J Dent. 2023;136:104603","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Adequate reporting of limitations is crucial to enable clinicians to accurately interpret the clinical trial findings. ... The reporting of limitations should not be viewed as a weakness of a trial but due diligence, so clinicians can fully"}},{"id":"engprof--academic-writing--writing-conclusion-body-paragraphs--v2","statement":"การ paraphrase ความคิดของผู้อื่นโดยไม่ให้เครดิตแหล่งที่มา ถือเป็น plagiarism เช่นเดียวกับการลอกคำต่อคำ และขอบเขตของคำว่า common knowledge เองก็ยังเป็นประเด็นที่สับสนกันอยู่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15381625","locator":"Abstract; Arch Surg. 2004;139(9):1022-1024","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Other acts of plagiarism are paraphrasing without crediting the source, using \"blanket\" references, \"second-generation\" references, and duplicate or repetitive publication of one's own previously published work. ... The requirement of many "}}]},"engprof--academic-writing--ama-citation-style-ที่ต้องรู้":{"claims":[{"id":"engprof--academic-writing--ama-citation-style-ที่ต้องรู้--v1","statement":"รายการอ้างอิงในวารสารการแพทย์ควรใส่ persistent identifier เช่น DOI, PMID หรือ ISBN และเลือกใช้ชื่อวารสารอย่างสม่ำเสมอ เพื่อให้ผู้อ่านตามไปหาต้นฉบับได้จริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39513084","locator":"Abstract; JMA J. 2024;7(4):461-470","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Key proposals include the use of persistent identifiers (Digital Object Identifier, PubMed Identifier, and International Standard Book Number), proper citation of online content, and the inclusion of romanized Japanese article titles. The s"}}]}},"engprof--summary-writing":{"engprof--summary-writing--what-is-a-summary":{"claims":[{"id":"engprof--summary-writing--what-is-a-summary--v1","statement":"กฎ Accurate (สรุปต้องอิงเฉพาะข้อมูลที่อยู่ใน original) ถูกละเมิดบ่อยแม้ในวารสารการแพทย์ใหญ่ การสุ่มตรวจ abstract ที่มากับ research article ในวารสาร 6 ฉบับ (Ann Intern Med, BMJ, JAMA, Lancet, NEJM, CMAJ) พบสัดส่วน abstract ที่ deficient คือมีข้อมูลขัดกับเนื้อความ (รวมตารางและรูป) หรือไม่พบในเนื้อความเลย อยู่ระหว่าง 18-68% และต่างกันอย่างมีนัยสำคัญระหว่างวารสาร (P<.001)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10188662","locator":"JAMA. 1999;281(12):1110-1","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Abstracts were considered deficient if they contained data that were either inconsistent with corresponding data in the article's body (including tables and figures) or not found in the body at all. The proportion of deficient abstracts var"}},{"id":"engprof--summary-writing--what-is-a-summary--v2","statement":"สำหรับ summary ของ RCT มีมาตรฐานกำหนดว่าต้องมีอะไรบ้าง คือ CONSORT for Abstracts ซึ่งแนะนำให้ abstract ใช้รูปแบบ structured และต้องมี trial objectives, trial design (เช่น method of allocation, blinding/masking), participants (คำอธิบาย จำนวนที่ randomize และจำนวนที่นำมาวิเคราะห์), interventions ของแต่ละกลุ่มพร้อมผลต่อ primary efficacy outcome และ harms, conclusions, ชื่อและเลขทะเบียน trial และแหล่งทุน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18215107","locator":"CONSORT for Abstracts checklist (PLoS Med. 2008;5(1):e20)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"CONSORT for Abstracts recommends that abstracts relating to RCTs have a structured format. Items should include details of trial objectives; trial design (e.g., method of allocation, blinding/masking); trial participants (i.e., description,"}}]},"engprof--summary-writing--5-rules-to-remember-final-criteria":{"claims":[{"id":"engprof--summary-writing--5-rules-to-remember-final-criteria--v1","statement":"กฎ Avoid inventing material และห้ามสรุปเกินข้อมูล มีหลักฐานเชิงประจักษ์: ใน RCT ที่ตรวจ abstract 203 ฉบับ พบ abstract ที่บกพร่อง 55 ฉบับ โดย 28 ฉบับ (51%) มีข้อมูลขัดกับเนื้อความ, 16 ฉบับ (29%) มีข้อมูลที่ไม่ปรากฏในเนื้อความ, 8 ฉบับ (15%) มีทั้งสองแบบ และ 3 ฉบับ (5%) มีข้อสรุปที่ข้อมูลใน abstract ไม่รองรับ ทั้งนี้การให้คำสั่งเฉพาะแก่ผู้เขียนไม่ช่วยลดอัตราความบกพร่อง (28% เทียบกับ 26%, P=.78)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9676677","locator":"JAMA. 1998;280(3):267-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Among 55 defective abstracts, 28 (51%) had inconsistencies, 16 (29%) contained data not present in the body, 8 (15%) had both types of defects, and 3 (5%) contained unjustified conclusions."}}]},"engprof--summary-writing--strategy-ใน-final-exam-part-ii":{"claims":[{"id":"engprof--summary-writing--strategy-ใน-final-exam-part-ii--v1","statement":"ข้อห้าม ห้ามใส่ opinion ของตัวเอง บอกแค่สิ่งที่ original บอก สอดคล้องกับปัญหา spin ที่พบจริงในวรรณกรรม: ในรายงาน RCT 72 เรื่องที่ primary outcome ไม่ significant พบ spin ในชื่อเรื่อง 13 เรื่อง (18.0%, 95% CI 10.0-28.9), ในส่วน Results ของ abstract 27 เรื่อง (37.5%) และในส่วน Conclusions ของ abstract 42 เรื่อง (58.3%) โดยมากกว่า 40% ของรายงานมี spin ในเนื้อความอย่างน้อย 2 sections","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20501928","locator":"JAMA. 2010;303(20):2058-64","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The title was reported with spin in 13 articles (18.0%; 95% CI, 10.0%-28.9%). Spin was identified in the Results and Conclusions sections of the abstracts of 27 (37.5%; 95% CI, 26.4%-49.7%) and 42 (58.3%; 95% CI, 46.1%-69.8%) reports, respe"}}]},"engprof--summary-writing--procedure-for-writing-summaries":{"claims":[{"id":"engprof--summary-writing--procedure-for-writing-summaries--v1","statement":"การสอนกลยุทธ์สรุปความอย่างชัดเจนช่วยให้เขียน summary ได้ดีขึ้นจริง โดยกลยุทธ์ generalization (รวมความคิดที่คล้ายกันขึ้นเป็นข้อความเดียว) ช่วยให้เขียนประโยคใจความหลักได้ดีกว่าอย่างมีนัยสำคัญ และกลยุทธ์สรุปความทั้งสองแบบช่วยให้ตัดสินได้ดีกว่าว่าเนื้อหาส่วนไหนสำคัญ เมื่อเทียบกับการให้ผู้เรียนใช้ความรู้สึกส่วนตัวตัดสินความสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11161637","locator":"Abstract; Contemp Educ Psychol. 2001;26(1):3-24","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Analysis of test summaries showed instruction in generalization was significantly more effective for stating a thesis statement. Both argument repetition and generalization were significantly more effective than the control condition in jud"}}]}},"engprof--research-design":{"engprof--research-design--observational-studies":{"claims":[{"id":"engprof--research-design--observational-studies--v1","statement":"Case-control study เริ่มจาก enroll กลุ่มที่เป็นโรค (cases) และกลุ่มที่ไม่เป็นโรค (controls) ก่อน แล้วจึงย้อนสืบประวัติ exposure ของแต่ละกลุ่ม จึงเป็น backward-direction study และเป็น retrospective เสมอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31008076","locator":"Vol 10, Issue 2, pages 91-94, section 'Case-control studies'","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In case-control studies, the researcher first enrolls cases (participants with the outcome) and controls (participants without the outcome) and then tries to elicit a history of exposure in each group. Thus, these are backward-direction stu"}},{"id":"engprof--research-design--observational-studies--v2","statement":"Case-control design เหมาะกับ rare diseases เพราะการหา cases ที่เป็นโรคทำได้ง่ายกว่าการตามกลุ่ม exposed จำนวนมากไปจนเกิด outcome แต่ข้อมูล exposure ต้องพึ่ง existing records หรือการซักประวัติ จึงเสี่ยง recall bias และ misinformation bias","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31008076","locator":"Vol 10, Issue 2, pages 91-94, sections 'Limitations of case-control studies' and 'Uses of case-control studies'","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Case-control studies are ideal for rare diseases, where identifying cases is easier than following up large numbers of exposed persons to determine outcome. ... The determination of exposure relies on existing records or history taking. Eit"}},{"id":"engprof--research-design--observational-studies--v3","statement":"Cohort study ตามกลุ่มที่มีระดับ exposure ต่างกันไปข้างหน้าตามเวลา โดยผู้เข้าร่วมต้องยังไม่มี outcome ตั้งแต่ baseline จึงเป็น forward-direction และโดยทั่วไปเป็น prospective และทำให้คำนวณ risk ของ outcome ในกลุ่ม exposed vs unexposed รวมถึง relative risk ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31008076","locator":"Vol 10, Issue 2, pages 91-94, sections 'Cohort studies' and 'Uses of cohort studies'","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Thus, cohort studies are forward-direction studies (moving from exposure to outcome) and are typically prospective studies (the outcome has not occurred at the start of the study). ... Since one starts with subjects known to have or not hav"}},{"id":"engprof--research-design--observational-studies--v4","statement":"Cross-sectional study เก็บข้อมูล exposure และ outcome ณ จุดเวลาเดียวในประชากรที่กำหนด เปรียบได้กับ snapshot และเหมาะที่สุดสำหรับการวัด prevalence ของโรคหรือของ risk factor","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30834206","locator":"Vol 10, Issue 1, pages 34-36, section 'Cross-sectional studies'","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cross-sectional studies can be thought of as providing a \"snapshot\" of the frequency and characteristics of a disease in a population at a particular point in time. These are very good for measuring the prevalence of a disease or of a risk "}}]},"engprof--research-design--interventional-experimental-studies":{"claims":[{"id":"engprof--research-design--interventional-experimental-studies--v1","statement":"RCT จัดสรรผู้เข้าร่วมไปแต่ละ arm ด้วยกระบวนการสุ่ม และถือเป็น gold standard ของ clinical research โดยวิธีจัดกลุ่มแบบ systematic ที่ไม่ใช่การสุ่มจะเปิดช่องให้เกิด selection bias และ confounding bias","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11853818","locator":"Vol 359, Issue 9305, pages 515-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The randomised controlled trial sets the gold standard of clinical research. However, randomisation persists as perhaps the least-understood aspect of a trial. Moreover, anything short of proper randomisation courts selection and confoundin"}},{"id":"engprof--research-design--interventional-experimental-studies--v2","statement":"การสุ่มเพียงอย่างเดียวยังไม่พอ: ในการวิเคราะห์ controlled trials 250 เรื่องจาก 33 meta-analyses trials ที่ allocation concealment ไม่เพียงพอให้ odds ratio เกินจริงประมาณ 41% และ trials ที่ไม่ได้ทำ double-blind ให้ odds ratio เกินจริงประมาณ 17%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7823387","locator":"Vol 273, Issue 5, pages 408-12","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Odds ratios were exaggerated by 41% for inadequately concealed trials and by 30% for unclearly concealed trials (adjusted for other aspects of quality). ... Trials that were not double-blind also yielded larger estimates of effects (P = .01"}}]},"engprof--research-design--other-designs-ที่อาจเจอ":{"claims":[{"id":"engprof--research-design--other-designs-ที่อาจเจอ--v1","statement":"Systematic review เป็น study design ที่สรุปผลจาก primary research studies หลายเรื่อง ส่วน meta-analysis คือเครื่องมือทางสถิติที่รวมผลของ studies เหล่านั้นเข้าด้วยกันเพื่อให้ได้ pooled estimate ของ treatment effect","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32670836","locator":"Vol 11, Issue 2, pages 97-100","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In this segment, we discuss systematic review, which is a study design used to summarize the results of several primary research studies. Systematic reviews often also use meta-analysis, which is a statistical tool to mathematically collate"}}]}},"engprof--paraphrasing":{"engprof--paraphrasing--what-is-paraphrasing":{"claims":[{"id":"engprof--paraphrasing--what-is-paraphrasing--v1","statement":"เมื่อ paraphrase ต้องอ้างอิง source เสมอ มิฉะนั้นถือเป็น plagiarism โดยในการตรวจ manuscripts ที่ส่งมายังวารสาร AJR พบ plagiarism 12 จาก 110 เรื่อง (10.9%) และใน 11 จาก 12 เรื่องนั้นขาดการอ้างอิงแหล่งต้นฉบับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28125269","locator":"Vol 208, Issue 4, pages 712-720","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Twelve manuscripts (10.9%) contained plagiarism. ... Referencing the original source was lacking in 11."}},{"id":"engprof--paraphrasing--what-is-paraphrasing--v2","statement":"Plagiarism มีผลจริงต่อ publication record: จากการทบทวน retracted biomedical และ life-science articles ทั้งหมด 2,047 เรื่องใน PubMed พบว่า 67.4% ถูกถอนเพราะ misconduct ซึ่งรวม duplicate publication 14.2% และ plagiarism 9.8% ขณะที่มีเพียง 21.3% ที่เกิดจาก error","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23027971","locator":"Vol 109, Issue 42, pages 17028-33","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A detailed review of all 2,047 biomedical and life-science research articles indexed by PubMed as retracted on May 3, 2012 revealed that only 21.3% of retractions were attributable to error. In contrast, 67.4% of retractions were attributab"}},{"id":"engprof--paraphrasing--what-is-paraphrasing--v3","statement":"การนำข้อความจากงานที่ตัวเองเคยตีพิมพ์มาใช้ซ้ำในงานใหม่โดยไม่อ้างอิงต้นฉบับ ก็เข้าข่าย plagiarism เช่นกัน เรียกว่า self-plagiarism หรือ text recycling","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30997390","locator":"Vol 5, Issue 2, pages 134-136","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This concept, also referred to as text recycling, is defined as the repurposing of one's own previously published work in new publications without referencing the original source."}}]},"engprof--paraphrasing--acceptable-vs-unacceptable-paraphrase":{"claims":[{"id":"engprof--paraphrasing--acceptable-vs-unacceptable-paraphrase--v1","statement":"Text-similarity detection software ใช้คัดกรอง plagiarism ได้ แต่ผลที่ถูก flag ต้องผ่านการตรวจสอบด้วยคนก่อน: ในการคัดกรอง manuscripts 754 เรื่องของ Croatian Medical Journal software flag ไว้ 105 เรื่อง (14%) แต่ยืนยันด้วยคนแล้วเป็น plagiarism จริง 85 เรื่อง (11%) แบ่งเป็น true plagiarism 63 เรื่อง (8%) และ self-plagiarism 22 เรื่อง (3%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22207497","locator":"Vol 18, Issue 2, pages 223-39","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of 754 submitted manuscripts, 105 (14%) were identified by the software as suspicious of plagiarism. Manual verification confirmed that 85 (11%) manuscripts were plagiarized: 63 (8%) were true plagiarism and 22 (3%) were self-plagiarism. .."}},{"id":"engprof--paraphrasing--acceptable-vs-unacceptable-paraphrase--v2","statement":"การ paraphrase แบบอัตโนมัติไม่รับประกันว่าจะพ้น plagiarism: เมื่อให้ ChatGPT paraphrase ข้อความ ค่าเฉลี่ย plagiarism rate ของข้อความที่ได้ยังอยู่ที่ 45% (SD 10%) แม้จะลดลงจากต้นฉบับอย่างมีนัยสำคัญก็ตาม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38989841","locator":"Vol 10, article e53308","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The average plagiarism rate in the texts generated by ChatGPT was 45% (SD 10%). ChatGPT exhibited a substantial reduction in plagiarism for the provided texts (mean difference -0.51, 95% CI -0.54 to -0.48; P<.001). ... Although ChatGPT demo"}}]},"engprof--paraphrasing--5-paraphrasing-techniques":{"claims":[{"id":"engprof--paraphrasing--5-paraphrasing-techniques--v1","statement":"การสลับ active กับ passive voice ใช้เป็นเทคนิค paraphrase ได้จริง และ passive voice พบมากในงานเขียนวิทยาศาสตร์ แต่ตัวกำหนดว่าควรเลือก voice ไหนคือลำดับข้อมูลในประโยค (ข้อมูลเดิมมาก่อน ข้อมูลใหม่ตามหลัง) ไม่ใช่เพราะ passive เป็นทางการกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25754358","locator":"Abstract; Keio J Med. 2015;64(1):1-10","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the key factor in voice selection is sentence word order as determined by the natural tendency in English for the topic of discourse (\"old\" information) to take subject position and for \"new\" information to come later. Authors who submit to"}},{"id":"engprof--paraphrasing--5-paraphrasing-techniques--v2","statement":"ในการเขียนบทความวิชาการ ควรหลีกเลี่ยงการยกข้อความจากบทความอ้างอิงมาตรงๆ และให้ paraphrase เป็นคำพูดของตัวเองแทน เพื่อไม่ให้เป็น plagiarism","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23478739","locator":"Abstract; JNMA J Nepal Med Assoc. 2012;52(186):95-101","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Language should be simple, active voice should be used and jargon avoided. Avoid directly quoting from reference articles and paraphrase these in your own words to avoid plagiarism."}}]}}};
